// test: does it match? (true / false)
/^\d{5}$/.test("90210");      // true: exactly five digits
/^\d{5}$/.test("9021");       // false
/hello/i.test("HeLLo world");  // true: i ignores case

// match: what matched?
"Order 42 and 7".match(/\d+/g);     // ["42", "7"]
"no numbers".match(/\d+/g);         // null (not an empty array!)

// replace: swap matches for something else
"a  b   c".replace(/\s+/g, " ");   // "a b c"
